IncompleteEmote`,`CompleteEmote`,`OfferRewardEmote1`,`OfferRewardEmoteDelay1`,`OfferRewardEmote2`,`OfferRewardEmoteDelay2`,`OfferRewardEmote3`,`OfferRewardEmoteDelay3`,`OfferRewardEmote4`,`OfferRewardEmoteDelay4`,`StartScript`,`CompleteScript`,`SpecialFlags`) VALUES
